// case.js — the B05 Correlation Analysis story: Lantern Coffee Co.'s two cafés in 2027, and what their daily log can
// and can't say about what goes with what. One source of truth for every figure B05's lessons, exercises,
// assessments and project use. Every name and number is invented for teaching; the data are generated by
// tools/study/b05-data.py with relationships planted (its header lists them), so every method can be checked against
// what is known to be true.
//
// The story. Lantern opened two cafés on 1 March 2027 (F03): Harbourside on the waterfront and Millbrook in the
// office district. Their managers keep a daily log: the day's high temperature and rain (Harbour City's weather
// station), the door counter's footfall, transactions and sales at the till, hot and iced drinks made, the barista
// hours rostered for the 7–11 a.m. peak, the average wait at the peak, and the loyalty app's members. At the end of
// the year Ana wants to know what goes with what — and which of those links she can act on.
//
// Agrees with other courses (checked in IDENTITIES): F03's two cafés, their names and opening day, their ten months of
// trading and their $236,000 of 2027 sales; F03's $189,400 of 2027 online sales (the project's weekly data). The peak
// barista hours are the 7–11 a.m. roster only, not the day's paid hours (F03 has the year's café wages).
import { CAFE_COLUMNS, CAFE_ROWS, SLIP, SHOP_COLUMNS, SHOP_WEEKS, OUTAGE_WEEK } from './data.js?v=20';
import { FACTS as F03 } from '../f03/case.js?v=20';
import * as C from '../../../core/correlation.js?v=20';
import { mean, sd } from '../../../core/stats.js?v=20';

export { CAFE_COLUMNS, CAFE_ROWS, SLIP };
/** The project's data (lessons, exercises and module tests must not use these). */
export { SHOP_COLUMNS, SHOP_WEEKS, OUTAGE_WEEK };

const at = (name) => CAFE_COLUMNS.indexOf(name);
const isSlip = (row) => row[at('date')] === SLIP.date && row[at('cafe')] === SLIP.cafe;
/** The log with the footfall slip corrected (the lessons' default; the outliers lesson starts from the raw log). */
export const CLEAN_ROWS = CAFE_ROWS.map((row) => (isSlip(row) ? row.map((v, i) => (i === at(SLIP.column) ? SLIP.actual : v)) : row));

/** A column of the log, optionally for one café, from the raw or the corrected log. Derived columns: iced_share
 *  (iced drinks ÷ all drinks), avg_ticket (sales ÷ transactions), peak_load (peak transactions ÷ peak barista hours,
 *  peak transactions being 55% of the day's), day (1 = 1 March). */
export function column(name, { cafe = null, raw = false } = {}) {
  const rows = (raw ? CAFE_ROWS : CLEAN_ROWS).filter((r) => !cafe || r[at('cafe')] === cafe);
  const dayOf = (r) => Math.round((Date.parse(r[at('date')]) - Date.parse('2027-03-01')) / 864e5) + 1;
  const f = {
    iced_share: (r) => r[at('iced_drinks')] / (r[at('iced_drinks')] + r[at('hot_drinks')]),
    avg_ticket: (r) => r[at('sales')] / r[at('transactions')],
    peak_load: (r) => r[at('transactions')] * 0.55 / r[at('peak_staff_hours')],
    day: dayOf,
  }[name];
  if (f) return rows.map(f);
  if (at(name) < 0) throw new Error(`b05 case: no column ${name}`);
  return rows.map((r) => r[at(name)]);
}
const cols = (names, opts) => Object.fromEntries(names.map((n) => [n, column(n, opts)]));
const r3 = (x) => Math.round(x * 1000) / 1000;
const pr = (a, b, opts) => C.pearson(column(a, opts), column(b, opts));
const sp = (a, b, opts) => C.spearman(column(a, opts), column(b, opts));

// ---------------------------------------------------------------- headline figures (recomputed by the checker)
const H = { cafe: 'Harbourside' }, M = { cafe: 'Millbrook' };
const window = (from, to, cafe) => CLEAN_ROWS.filter((r) => r[at('cafe')] === cafe && r[at('date')] >= from && r[at('date')] <= to);
const winR = (rows, a, b) => C.pearson(rows.map((r) => r[at(a)]), rows.map((r) => r[at(b)])).r;
const hSpring = window('2027-03-01', '2027-07-31', 'Harbourside'), hAutumn = window('2027-08-01', '2027-12-31', 'Harbourside');

export const DERIVED = {
  rows: CAFE_ROWS.length, days: CAFE_ROWS.length / 2,
  salesTotal: column('sales').reduce((s, v) => s + v, 0),
  salesHarbourside: column('sales', H).reduce((s, v) => s + v, 0),
  salesMillbrook: column('sales', M).reduce((s, v) => s + v, 0),
  // the iced-drink curve
  tempIced: pr('high_f', 'iced_share'), tempIcedRho: sp('high_f', 'iced_share'), tempHot: pr('high_f', 'hot_drinks'),
  // rain is zero on most days
  rainDays: column('rain_in').filter((v) => v > 0).length, rainFootfall: pr('rain_in', 'footfall'), rainFootfallH: pr('rain_in', 'footfall', H),
  // the chain, and the slip
  footTrans: pr('footfall', 'transactions'), footTransRaw: pr('footfall', 'transactions', { raw: true }),
  footTransRhoRaw: sp('footfall', 'transactions', { raw: true }), transSales: pr('transactions', 'sales'),
  // staffing: correlated with sales and with waits, though baristas shorten waits
  staffSales: pr('peak_staff_hours', 'sales'), staffWait: pr('peak_staff_hours', 'peak_wait_min'),
  staffWaitGivenTrans: C.partial(column('peak_staff_hours'), column('peak_wait_min'), [column('transactions')]),
  loadWait: pr('peak_load', 'peak_wait_min'), loadWaitRho: sp('peak_load', 'peak_wait_min'),
  // Simpson's paradox: footfall and average ticket
  footTicket: pr('footfall', 'avg_ticket'), footTicketH: pr('footfall', 'avg_ticket', H), footTicketM: pr('footfall', 'avg_ticket', M),
  meanFootfallH: mean(column('footfall', H)), meanFootfallM: mean(column('footfall', M)),
  meanTicketH: mean(column('avg_ticket', H)), meanTicketM: mean(column('avg_ticket', M)),
  // two trends: Harbourside's loyalty members against the day's high, spring and autumn
  membersTempSpring: winR(hSpring, 'high_f', 'loyalty_members'), membersTempAutumn: winR(hAutumn, 'high_f', 'loyalty_members'),
  sdHigh: sd(column('high_f')),
};

/** A ready correlation matrix of the main daily measures (both cafés, corrected log). */
export const MATRIX_COLUMNS = ['high_f', 'rain_in', 'footfall', 'transactions', 'sales', 'iced_share', 'peak_staff_hours', 'peak_wait_min'];
export const MATRIX = C.matrix(cols(MATRIX_COLUMNS), { adjustMethod: 'holm' });

const shopAt = (n) => SHOP_COLUMNS.indexOf(n);
export const IDENTITIES = [
  ['612 rows: two cafés × 306 days', CAFE_ROWS.length === 612],
  ['306 days = 1 March – 31 December 2027, the ten months F03 says the cafés traded', CAFE_ROWS[0][at('date')] === F03.cafes.opened && CAFE_ROWS.at(-1)[at('date')] === '2027-12-31' && F03.cafes.months === 10],
  ['the cafés are F03’s', JSON.stringify([...new Set(CAFE_ROWS.map((r) => r[at('cafe')]))]) === JSON.stringify(F03.cafes.names)],
  ['café sales total F03’s $236,000', Math.round(DERIVED.salesTotal * 100) === F03.cafes.sales * 100],
  ['the slip is the only change between the raw and corrected log', CAFE_ROWS.filter((r, i) => JSON.stringify(r) !== JSON.stringify(CLEAN_ROWS[i])).length === 1],
  ['the slip adds a digit to the true value', String(SLIP.recorded).length === String(SLIP.actual).length + 1],
  ['iced + hot drinks are at least the transactions on most days', column('transactions').filter((t, i) => column('iced_drinks')[i] + column('hot_drinks')[i] >= t * 0.9).length > 600],
  ['the project’s 52 weeks total F03’s $189,400 of online sales', Math.round(SHOP_WEEKS.reduce((s, w) => s + w[shopAt('order_value')], 0) * 100) === F03.shop.sales * 100],
  ['the project’s paid-social spend is a small part of F03’s $11,500 of 2027 advertising (mostly the cafés’ opening)', SHOP_WEEKS.reduce((s, w) => s + w[shopAt('social_spend')], 0) < F03.advertising / 3],
  ['the project’s orders at B03’s $5.20 a parcel come within 1% of F03’s $20,300 of 2027 shipping', Math.abs(SHOP_WEEKS.reduce((s, w) => s + w[shopAt('orders')], 0) * 5.20 / F03.shipping - 1) < 0.01],
  ['the project covers 1 January – 31 December 2027', SHOP_WEEKS[0][shopAt('starts')] === '2027-01-01' && SHOP_WEEKS.reduce((s, w) => s + w[shopAt('days')], 0) === 365],
  ['planted: Simpson’s reversal (pooled negative, both cafés positive)', DERIVED.footTicket.r < 0 && DERIVED.footTicketH.r > 0 && DERIVED.footTicketM.r > 0],
  ['planted: staffing goes with longer waits, but shortens them at a given number of transactions', DERIVED.staffWait.r > 0 && DERIVED.staffWaitGivenTrans.r < 0],
  ['planted: two trends flip sign', DERIVED.membersTempSpring > 0.5 && DERIVED.membersTempAutumn < -0.5],
];
